// Deployment de juguete: reemplaza pods v1 por v2 respetando maxSurge y maxUnavailable.
function rollout({ replicas, maxSurge, maxUnavailable, v2Sana }) {
  let n = 0;
  const nuevo = (v) => ({ id: `${v}-${++n}`, v, listo: v === 'v1', edad: 0 });
  let pods = Array.from({ length: replicas }, () => nuevo('v1'));
  for (let t = 1; t <= 10; t++) {
    // 1. la sonda de disponibilidad: la v2 sana pasa a "lista" a los 2 pasos
    for (const p of pods) { p.edad++; if (p.v === 'v2' && v2Sana && p.edad >= 2) p.listo = true; }
    // 2. crear pods nuevos mientras no se pase del tope (replicas + maxSurge)
    while (pods.length < replicas + maxSurge && pods.filter((p) => p.v === 'v2').length < replicas) pods.push(nuevo('v2'));
    // 3. borrar viejos mientras queden al menos (replicas - maxUnavailable) listos
    while (pods.some((p) => p.v === 'v1') && pods.filter((p) => p.listo).length - 1 >= replicas - maxUnavailable) {
      pods.splice(pods.findIndex((p) => p.v === 'v1'), 1);
    }
    // 4. si faltan pods para llegar a replicas y ya no hay viejos que borrar, completar con nuevos
    while (pods.length < replicas && pods.filter((p) => p.v === 'v2').length < replicas) pods.push(nuevo('v2'));
    const sirven = pods.filter((p) => p.listo).map((p) => p.id);
    console.log(`paso ${String(t).padStart(2)} | pods: ${pods.map((p) => p.id + (p.listo ? '' : '?')).join(' ')} | atienden: ${sirven.length}`);
    if (pods.length === replicas && pods.every((p) => p.v === 'v2' && p.listo)) { console.log('terminó: todo en v2'); return; }
  }
  console.log('sigue a medias después de 10 pasos');
}
