// Un Service de juguete: no guarda una lista de pods, la recalcula con etiquetas y estado.
const pods = [
  { nombre: 'despachos-a1', ip: '10.1.0.11', etiquetas: { app: 'despachos', version: 'v1' }, listo: true },
  { nombre: 'despachos-b2', ip: '10.1.0.12', etiquetas: { app: 'despachos', version: 'v1' }, listo: true },
  { nombre: 'despachos-c3', ip: '10.1.1.7',  etiquetas: { app: 'despachos', version: 'v2' }, listo: false },
  { nombre: 'reportes-d4',  ip: '10.1.1.8',  etiquetas: { app: 'reportes' },                 listo: true },
  { nombre: 'despachos-e5', ip: '10.1.0.13', etiquetas: { app: 'despacho' },                 listo: true }, // typo
];
const coincide = (selector, etiquetas) => Object.entries(selector).every(([k, v]) => etiquetas[k] === v);
const endpoints = (selector) => pods.filter((p) => p.listo && coincide(selector, p.etiquetas)).map((p) => p.ip + ':3000');

